    h, w = len(grid), len(grid[0])
    # The repeated color-3 vertical marks are the ray direction indicator;
    # continue the sequence down the same column to the edge.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 3]
        if len(rows) >= 2 and rows == list(range(min(rows), max(rows)+1)):
            for r in range(max(rows)+1, h):
                if grid[r][c] == grid[0][0]:
                    out[r][c] = 3
    return out

